import { memo, useRef } from "react";

type ChildProps = { onClick: (label: string) => void };

// The child is memo()-wrapped, so it should skip re-rendering while its props are
// shallow-equal. It counts its own renders into a data-testid the tests can read.
// Do NOT edit this file — the fix belongs in Parent.tsx.
export const Child = memo(function Child({ onClick }: ChildProps) {
  const renders = useRef(0);
  renders.current += 1;

  return (
    <div>
      <p data-testid="child-renders">{renders.current}</p>
      <button onClick={() => onClick("child")}>Child action</button>
    </div>
  );
});
